"""Reproducible, original reading pack. No network calls or changes to existing lessons.

Levels are editorial estimates, not CEFR certification. IELTS-tagged passages are
short skill exercises about explicitly hypothetical projects, not official tests.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PACK = []

def lesson(slug, title, level, topic, summary, pairs, words, questions, track='general'):
    paragraphs = [p[0] for p in pairs]
    vocabulary = []
    for word, meaning, index in words:
        vocabulary.append(dict(word=word,pos='word / phrase',meaning_vi=meaning,
            synonyms=[],paraphrases=[],context=paragraphs[index],paragraph_index=index,
            example='',example_vi='',note='',tags=[level,topic]))
    qs=[]
    for i,(kind,prompt,options,answer,index,evidence,explanation) in enumerate(questions):
        # Distribute correct choices while preserving the fixed TRUE/FALSE/NOT GIVEN labels.
        if kind!='tfng':
            shift=(len(PACK)+i)%len(options)
            options=options[shift:]+options[:shift]
            answer=(answer-shift)%len(options)
        qs.append(dict(id=f'q{i+1}',kind=kind,prompt=prompt,options=options,answer=answer,
            paragraph_index=index,evidence=evidence,explanation_vi=explanation))
    PACK.append(dict(slug=slug,title=title,level=level,topic=topic,summary=summary,track=track,
        revision=1,order=100+len(PACK),published=True,author='LexiRead',
        provenance='Bài luyện gốc do LexiRead biên soạn. Nhân vật và dự án trong bài là giả định. Không phải đề thi chính thức.',
        level_note='Mức đọc do người biên soạn ước lượng; không phải chứng nhận CEFR hoặc band IELTS.',
        text='\n\n'.join(paragraphs),analysis=dict(translations=[dict(index=i,vi=p[1]) for i,p in enumerate(pairs)],vocabulary=vocabulary,grammar=[]),
        questions=qs,faqs=[]))

TF=['TRUE','FALSE','NOT GIVEN']

lesson('a1-the-red-notebook','The Red Notebook','A1','Trường học','Một cuốn vở nhỏ giúp An nhớ những điều mới mỗi ngày.',[
("An has a small red notebook. He takes it to school every day. In the morning, he writes three English words in it. He does not write long sentences. He draws a small picture next to each word.","An có một cuốn vở nhỏ màu đỏ. Em mang nó đến trường mỗi ngày. Buổi sáng, em viết ba từ tiếng Anh vào vở. Em không viết câu dài. Em vẽ một bức tranh nhỏ bên cạnh mỗi từ."),
("After lunch, An opens the notebook with his friend Lan. Lan looks at the pictures and says the words. Then An closes the book and tries to remember them. Sometimes he forgets a word. Lan helps him, and they try again.","Sau bữa trưa, An mở vở cùng bạn Lan. Lan nhìn tranh và đọc các từ. Sau đó An đóng vở và cố nhớ lại. Đôi khi em quên một từ. Lan giúp em và cả hai thử lại."),
("At home, An shows one new word to his father. Today the word is garden. They look out of the window together. There is a little garden outside. An smiles. Now the word is part of his day.","Ở nhà, An chỉ cho bố một từ mới. Hôm nay đó là từ garden, nghĩa là khu vườn. Hai bố con cùng nhìn ra cửa sổ. Bên ngoài có một khu vườn nhỏ. An mỉm cười. Giờ đây từ đó là một phần trong ngày của em.")],
[('notebook','cuốn vở',0),('draws','vẽ',0),('remember','nhớ',1),('garden','khu vườn',2)],[
('detail','What does An draw beside each word?',['A small picture','A long sentence','A number'],0,0,'He draws a small picture next to each word.','An vẽ một bức tranh nhỏ bên cạnh mỗi từ.'),
('detail','Who studies with An after lunch?',['Lan','His father','His teacher'],0,1,'After lunch, An opens the notebook with his friend Lan.','Lan cùng An xem vở sau bữa trưa.'),
('tfng','An writes ten new words every morning.',TF,1,0,'he writes three English words in it.','Bài nói ba từ, không phải mười từ: FALSE.')])

lesson('a1-a-bus-to-the-park','A Bus to the Park','A1','Đi lại','Đọc lịch xe buýt và tìm đường đến công viên cùng Linh.',[
("It is Saturday. Linh wants to visit the park with her brother. They walk to the bus stop near their home. A sign says that bus number eight goes to the park. The next bus comes at nine o'clock.","Hôm nay là thứ Bảy. Linh muốn đến công viên cùng em trai. Hai chị em đi bộ đến trạm xe buýt gần nhà. Một tấm biển cho biết xe buýt số tám đến công viên. Chuyến tiếp theo đến lúc chín giờ."),
("They wait on a bench. Her brother has a blue bag with two bottles of water. Linh has some bread. When the bus arrives, they get on and sit near the front. They can see the shops through the window.","Hai chị em ngồi chờ trên ghế. Em trai mang một chiếc túi xanh có hai chai nước. Linh mang ít bánh mì. Khi xe đến, họ lên xe và ngồi gần phía trước. Qua cửa sổ, họ nhìn thấy các cửa hàng."),
("The driver stops outside the park. Linh thanks him. The children find a quiet place under a tree and eat their bread. They do not need to hurry. Their bus home leaves in the afternoon.","Tài xế dừng bên ngoài công viên. Linh cảm ơn bác. Hai chị em tìm một chỗ yên tĩnh dưới gốc cây và ăn bánh mì. Họ không cần vội. Xe về nhà khởi hành vào buổi chiều.")],
[('bus stop','trạm xe buýt',0),('wait','chờ',1),('arrives','đến',1),('hurry','vội',2)],[
('detail','Which bus goes to the park?',['Number eight','Number two','Number nine'],0,0,'bus number eight goes to the park.','Xe số tám đến công viên; chín là giờ xe đến.'),
('detail','Where do the children eat?',['Under a tree','In a shop','On the bus'],0,2,'under a tree and eat their bread.','Hai chị em ăn dưới gốc cây.'),
('tfng','Linh and her brother sit near the back of the bus.',TF,1,1,'sit near the front.','Họ ngồi gần phía trước, không phải phía sau.')])

lesson('a1-soup-for-a-neighbour','Soup for a Neighbour','A1','Gia đình & hàng xóm','Một bữa trưa đơn giản và một việc tử tế dành cho hàng xóm.',[
("On Sunday, Ben helps his mother make soup. He washes carrots and potatoes. His mother cuts them into small pieces. There is a big pot on the stove. The kitchen is warm, and Ben is hungry.","Chủ nhật, Ben giúp mẹ nấu súp. Em rửa cà rốt và khoai tây. Mẹ cắt chúng thành miếng nhỏ. Có một chiếc nồi lớn trên bếp. Căn bếp ấm áp và Ben thấy đói."),
("Their neighbour, Mrs Green, is at home today. Her leg hurts, so she cannot go to the market. Ben's mother puts some soup in a box. Ben carries the box carefully to the house next door. He also takes a spoon.","Hôm nay hàng xóm của họ, bà Green, ở nhà. Bà đau chân nên không thể đi chợ. Mẹ Ben cho một ít súp vào hộp. Ben cẩn thận mang hộp sang nhà bên cạnh. Em cũng mang theo một chiếc thìa."),
("Mrs Green opens the door and smiles. She says thank you and asks about Ben's school. They talk for a few minutes. When Ben goes home, his own lunch is ready. He tells his mother that Mrs Green likes the soup.","Bà Green mở cửa và mỉm cười. Bà cảm ơn và hỏi về trường của Ben. Họ trò chuyện vài phút. Khi Ben về nhà, bữa trưa của em đã sẵn sàng. Em nói với mẹ rằng bà Green thích món súp.")],
[('hungry','đói',0),('neighbour','hàng xóm',1),('carefully','cẩn thận',1),('ready','sẵn sàng',2)],[
('detail','Why does Mrs Green stay at home?',['Her leg hurts','She is cooking for Ben','The market is closed'],0,1,'Her leg hurts, so she cannot go to the market.','Bà đau chân nên không thể đi chợ.'),
('detail','What does Ben carry with the soup?',['A spoon','Some flowers','A book'],0,1,'He also takes a spoon.','Ben mang theo một chiếc thìa.'),
('tfng','Mrs Green asks Ben about his school.',TF,0,2,'asks about Ben\'s school.','Thông tin được nêu trực tiếp: TRUE.')])

lesson('a1-the-library-card','The Library Card','A1','Sách & thư viện','Tìm cuốn sách đầu tiên và đọc thông tin trên thẻ thư viện.',[
("Sara visits the town library for the first time. She wants a book about animals. A woman at the desk asks for her name. Sara writes it on a form. The woman gives her a library card and shows her the children's room.","Sara đến thư viện thị trấn lần đầu tiên. Em muốn một cuốn sách về động vật. Một cô ở quầy hỏi tên em. Sara viết tên lên mẫu đơn. Cô đưa cho em một thẻ thư viện và chỉ phòng sách thiếu nhi."),
("The room has low shelves and bright windows. Sara finds a book with a bird on the cover. There are large pictures inside. She sits on a green chair and reads two pages. Some words are new, but the pictures help her understand.","Căn phòng có những kệ thấp và cửa sổ sáng sủa. Sara tìm thấy cuốn sách có hình chim trên bìa. Bên trong có những bức tranh lớn. Em ngồi trên ghế xanh và đọc hai trang. Một số từ còn mới nhưng tranh giúp em hiểu."),
("Sara can take the book home for two weeks. The return date is on a small piece of paper. She puts the paper inside the book. Before she leaves, she asks about the next story morning. It is on Saturday, and she wants to come back.","Sara có thể mang sách về trong hai tuần. Ngày trả sách được ghi trên một mảnh giấy nhỏ. Em đặt mảnh giấy vào sách. Trước khi ra về, em hỏi về buổi kể chuyện tiếp theo. Buổi đó diễn ra vào thứ Bảy và em muốn quay lại.")],
[('library','thư viện',0),('shelves','các kệ sách',1),('cover','bìa',1),('return date','ngày trả sách',2)],[
('detail','What kind of book does Sara want?',['A book about animals','A book about cooking','A book about trains'],0,0,'She wants a book about animals.','Sara muốn sách về động vật.'),
('detail','How long can she keep the book?',['Two weeks','Two days','One month'],0,2,'Sara can take the book home for two weeks.','Thời hạn mượn là hai tuần.'),
('tfng','Sara understands every word in the book.',TF,1,1,'Some words are new, but the pictures help her understand.','Một số từ mới đối với Sara, nên không phải em hiểu mọi từ.')])

lesson('a2-the-weekend-market','The Weekend Market','A2','Mua sắm','Lên kế hoạch mua hàng và thay đổi lựa chọn khi đến chợ.',[
("Nora usually bought vegetables at the supermarket on her way home from work. Last Saturday, she tried the small outdoor market near the station. Before leaving home, she made a shopping list and put two cloth bags by the door. She wanted enough food for three simple dinners, not a fridge full of things she might forget.","Nora thường mua rau ở siêu thị trên đường đi làm về. Thứ Bảy tuần trước, cô thử đến chợ nhỏ ngoài trời gần ga. Trước khi ra khỏi nhà, cô lập danh sách mua sắm và đặt hai túi vải cạnh cửa. Cô muốn đủ thức ăn cho ba bữa tối đơn giản, không phải một tủ lạnh đầy những thứ có thể bị quên."),
("At the first stall, the tomatoes were more expensive than she expected. The seller explained that the heavy rain had damaged some plants. Nora chose carrots instead. She asked how to keep them fresh, and the seller told her to put them in a cool place. At another stall, she found a small bag of rice.","Ở quầy đầu tiên, cà chua đắt hơn cô nghĩ. Người bán giải thích mưa lớn đã làm hỏng một số cây. Nora chọn cà rốt thay thế. Cô hỏi cách giữ chúng tươi và được khuyên để ở nơi mát. Tại một quầy khác, cô tìm được một túi gạo nhỏ."),
("Nora did not buy everything on her list, but she had what she needed. That evening, she cooked rice and vegetables. She wrote the total cost in her notebook so she could compare it with her usual shopping. She decided to return the next weekend, partly because she enjoyed talking to the people who sold her food.","Nora không mua hết danh sách nhưng có những thứ cần thiết. Tối đó, cô nấu cơm và rau. Cô ghi tổng chi phí vào vở để so sánh với việc mua sắm thường ngày. Cô quyết định quay lại vào cuối tuần sau, một phần vì thích trò chuyện với người bán thức ăn cho mình.")],
[('shopping list','danh sách mua sắm',0),('cloth bags','túi vải',0),('stall','quầy hàng',1),('instead','thay vào đó',1),('compare','so sánh',2),('partly','một phần',2)],[
('detail','Why did Nora choose carrots?',['The tomatoes cost more than expected','She did not like tomatoes','There were no other vegetables'],0,1,'the tomatoes were more expensive than she expected.','Giá cà chua cao hơn dự kiến khiến cô đổi lựa chọn.'),
('detail','Why did she record the total cost?',['To compare shopping costs','To send the seller a bill','To plan a party'],0,2,'so she could compare it with her usual shopping.','Cô muốn so sánh chi phí với cách mua sắm thường ngày.'),
('tfng','Nora bought everything on her list.',TF,1,2,'Nora did not buy everything on her list','Bài phủ định trực tiếp nhận định này: FALSE.')])

lesson('a2-learning-to-swim','Learning to Swim Again','A2','Thể thao','Một người lớn học bơi theo từng bước nhỏ thay vì so sánh với người khác.',[
("When David joined a swimming class, he felt nervous. He could stand in the shallow end of the pool, but he did not like putting his face in the water. Most people in his group were beginners too. Their teacher, Eva, said that the first lesson was about feeling comfortable, not swimming quickly.","Khi tham gia lớp bơi, David cảm thấy lo. Anh có thể đứng ở đầu nông của bể nhưng không thích úp mặt xuống nước. Phần lớn người trong nhóm cũng mới bắt đầu. Giáo viên Eva nói bài học đầu tiên nhằm tạo cảm giác thoải mái, chứ không phải bơi nhanh."),
("Eva showed them how to breathe out into the water. David practised while holding the side of the pool. At first, he stopped after a few seconds. Eva asked him to rest and try again when he was ready. By the end of the lesson, he could keep his face in the water for longer without feeling afraid.","Eva hướng dẫn họ thở ra trong nước. David tập trong khi bám thành bể. Ban đầu anh dừng sau vài giây. Eva bảo anh nghỉ và thử lại khi sẵn sàng. Cuối buổi, anh có thể úp mặt trong nước lâu hơn mà không thấy sợ."),
("At home, David wanted to watch videos of fast swimmers. Then he remembered Eva's advice: compare your progress with your own first day. He booked another lesson. He still could not swim across the pool, but he had learned something useful. For him, coming back was already a success.","Về nhà, David muốn xem video những người bơi nhanh. Rồi anh nhớ lời Eva: hãy so tiến bộ với ngày đầu của chính mình. Anh đặt buổi học tiếp theo. Anh vẫn chưa bơi hết bể nhưng đã học được điều hữu ích. Với anh, quay lại học đã là một thành công.")],
[('shallow','nông',0),('beginners','người mới bắt đầu',0),('breathe out','thở ra',1),('afraid','sợ',1),('progress','sự tiến bộ',2),('success','thành công',2)],[
('detail','What was the aim of the first lesson?',['Feeling comfortable in water','Swimming as fast as possible','Crossing the whole pool'],0,0,'the first lesson was about feeling comfortable, not swimming quickly.','Buổi đầu tập trung vào cảm giác thoải mái trong nước.'),
('detail','What did Eva tell David to compare?',['His progress with his first day','His speed with expert swimmers','The prices of different pools'],0,2,'compare your progress with your own first day.','Điểm so sánh là chính bản thân David trong ngày đầu.'),
('tfng','David could swim across the pool after his first lesson.',TF,1,2,'He still could not swim across the pool','Anh vẫn chưa bơi hết bể: FALSE.')])

lesson('b1-the-shared-tool-shelf','The Shared Tool Shelf','B1','Cộng đồng','Một tủ dụng cụ chung cần cả sự tin tưởng lẫn những quy tắc dễ hiểu.',[
("When a shelf fell down in her flat, Amina realised that she owned plenty of books but no drill. Buying a tool for one small job seemed wasteful. She asked in her building's message group, and three neighbours offered to lend her one. Their replies gave her an idea: perhaps the building could have a shared tool shelf in the entrance hall.","Khi một chiếc kệ trong căn hộ rơi xuống, Amina nhận ra mình có nhiều sách nhưng không có máy khoan. Mua dụng cụ chỉ cho một việc nhỏ có vẻ lãng phí. Cô hỏi trong nhóm nhắn tin của tòa nhà và ba hàng xóm ngỏ ý cho mượn. Những câu trả lời gợi cho cô ý tưởng đặt một tủ dụng cụ chung ở sảnh."),
("The neighbours liked the idea, but they disagreed about how it should work. One person wanted a deposit for every item. Another thought this would discourage people from borrowing. They eventually chose a simpler system: borrowers wrote their name and return date in a notebook. The shelf held only basic hand tools. Electrical tools remained with their owners, who could explain how to use them safely.","Hàng xóm thích ý tưởng nhưng bất đồng về cách vận hành. Một người muốn thu tiền đặt cọc từng món; người khác nghĩ điều đó sẽ khiến mọi người ngại mượn. Cuối cùng họ chọn cách đơn giản hơn: người mượn ghi tên và ngày trả vào sổ. Tủ chỉ có dụng cụ cầm tay cơ bản. Dụng cụ điện vẫn do chủ giữ để hướng dẫn cách dùng an toàn."),
("After a month, most items had been returned on time. A missing hammer caused some concern until its borrower explained that she had left it with another neighbour. The group added one rule: return a tool before passing it to somebody else. Amina learned that sharing did not mean having no rules. It meant making rules that people could understand and actually follow.","Sau một tháng, phần lớn dụng cụ được trả đúng hạn. Một chiếc búa mất khiến mọi người lo, cho đến khi người mượn giải thích đã đưa nó cho hàng xóm khác. Nhóm thêm một quy tắc: trả dụng cụ trước khi chuyển cho người khác. Amina hiểu rằng chia sẻ không có nghĩa là không có quy tắc, mà là có quy tắc dễ hiểu và có thể thực hiện.")],
[('wasteful','lãng phí',0),('lend','cho mượn',0),('deposit','tiền đặt cọc',1),('discourage','khiến ai ngại hoặc không muốn làm',1),('concern','sự lo ngại',2),('follow','tuân theo',2)],[
('detail','Why did Amina first contact her neighbours?',['She needed to borrow a drill','She wanted to sell her books','She was moving out'],0,0,'she owned plenty of books but no drill.','Cô cần máy khoan để xử lý chiếc kệ.'),
('detail','Why were electrical tools kept by their owners?',['Owners could explain safe use','The entrance hall was too cold','Borrowers refused to pay a deposit'],0,1,'their owners, who could explain how to use them safely.','Chủ dụng cụ có thể hướng dẫn sử dụng an toàn.'),
('tfng','The neighbours decided to collect a deposit for every tool.',TF,1,1,'They eventually chose a simpler system: borrowers wrote their name and return date in a notebook.','Tiền đặt cọc chỉ là đề xuất. Nhóm chọn hệ thống ghi tên và ngày trả.')])

lesson('b1-a-different-lunch-break','A Different Lunch Break','B1','Công việc & cân bằng','Thử thay đổi giờ nghỉ trưa và nhìn lại điều thật sự có ích.',[
("For months, Leo had eaten lunch at his desk while answering messages. He believed that this habit saved time. Yet by mid-afternoon, he often reread the same paragraph without understanding it. When a colleague invited him on a short lunchtime walk, he almost refused. There were still several tasks on his list, and leaving the office felt irresponsible.","Suốt nhiều tháng, Leo ăn trưa tại bàn trong khi trả lời tin nhắn. Anh tin thói quen ấy tiết kiệm thời gian. Nhưng đến giữa chiều, anh thường đọc lại cùng một đoạn mà không hiểu. Khi đồng nghiệp rủ đi bộ ngắn vào giờ trưa, anh suýt từ chối. Danh sách vẫn còn nhiều việc và rời văn phòng khiến anh cảm thấy thiếu trách nhiệm."),
("He agreed to try it for a week. They walked slowly around the block, without checking their phones. Some days they talked about work; on others they noticed the changing displays in a shop window. Leo still had busy afternoons, but returning to his desk felt less difficult. He began writing down which tasks he finished instead of counting only the minutes he spent sitting there.","Anh đồng ý thử trong một tuần. Họ đi chậm quanh khu nhà, không kiểm tra điện thoại. Có ngày họ nói về công việc, ngày khác họ để ý những thay đổi trong tủ trưng bày của cửa hàng. Buổi chiều của Leo vẫn bận nhưng trở lại bàn làm việc có vẻ bớt khó khăn. Anh bắt đầu ghi những việc hoàn thành thay vì chỉ đếm số phút ngồi tại bàn."),
("The experiment did not solve every problem. On rainy days, Leo preferred to eat in the shared kitchen. He also learned that his colleague enjoyed walking alone sometimes. They stopped treating the walk as a daily appointment and kept it as an option. The useful change was not a particular route or companion. It was allowing himself a real break.","Thử nghiệm không giải quyết mọi vấn đề. Ngày mưa, Leo thích ăn trong bếp chung. Anh cũng biết đồng nghiệp đôi khi thích đi một mình. Họ không còn coi cuộc đi bộ là lịch hẹn bắt buộc mỗi ngày mà giữ nó như một lựa chọn. Thay đổi hữu ích không nằm ở tuyến đường hay người đi cùng, mà ở việc cho phép bản thân nghỉ thực sự.")],
[('habit','thói quen',0),('refused','từ chối',0),('displays','các phần trưng bày',1),('finished','hoàn thành',1),('companion','người đồng hành',2),('allowing','cho phép',2)],[
('detail','What did Leo originally think about eating at his desk?',['It saved time','It made food taste better','It helped his colleagues'],0,0,'He believed that this habit saved time.','Leo ban đầu tin rằng ăn tại bàn giúp tiết kiệm thời gian.'),
('detail','What did Leo start recording?',['Tasks he completed','The length of every street','How many shops were open'],0,1,'writing down which tasks he finished','Anh chuyển sang ghi nhận kết quả công việc.'),
('tfng','Leo and his colleague continued to walk together every day.',TF,1,2,'They stopped treating the walk as a daily appointment and kept it as an option.','Họ giữ đi bộ như một lựa chọn, không phải lịch hẹn hằng ngày.')])

lesson('b2-when-a-map-leaves-things-out','When a Map Leaves Things Out','B2','Thiết kế & tiếp cận','Một bản đồ dễ nhìn chưa chắc giúp mọi người tìm được đường.',[
("A volunteer team was asked to redesign the map of a community arts centre. The existing version showed every storage room and service corridor, making the building appear far more complicated than it felt in person. The designers removed unnecessary details and used a different colour for each floor. At the first review, staff praised its clean appearance and assumed that visitors would find it equally helpful.","Một nhóm tình nguyện được giao thiết kế lại bản đồ trung tâm nghệ thuật cộng đồng. Bản cũ thể hiện mọi kho và hành lang kỹ thuật, khiến tòa nhà trông phức tạp hơn thực tế. Nhóm bỏ chi tiết không cần thiết và dùng màu khác nhau cho từng tầng. Ở buổi đánh giá đầu tiên, nhân viên khen hình thức rõ ràng và cho rằng khách cũng sẽ thấy hữu ích."),
("However, a trial with new visitors exposed problems that the review had missed. The shortest route to the main gallery included a staircase, but this was not obvious on the simplified map. A visitor using a wheelchair had to return to reception to ask for another route. Meanwhile, someone who could not easily distinguish the floor colours confused two meeting rooms. The map was visually quieter, yet some of its most important information had disappeared.","Tuy nhiên, thử nghiệm với khách mới bộc lộ những vấn đề buổi đánh giá bỏ sót. Lối ngắn nhất đến phòng trưng bày có cầu thang nhưng bản đồ đơn giản không thể hiện rõ. Một khách dùng xe lăn phải quay lại quầy để hỏi lối khác. Một người khó phân biệt màu các tầng lại nhầm hai phòng họp. Bản đồ ít rối hơn về thị giác nhưng mất một số thông tin quan trọng nhất."),
("The team revised the design rather than restoring every deleted detail. They marked step-free routes clearly and added floor numbers alongside colours. They also tested the map with people who had never visited the centre. This time, success was measured by whether visitors reached their destinations without assistance. The experience suggested that simplicity is not merely the absence of detail. It depends on retaining the details that different users need.","Nhóm sửa thiết kế thay vì khôi phục mọi chi tiết đã xóa. Họ đánh dấu rõ lối đi không có bậc và thêm số tầng bên cạnh màu. Họ cũng thử với người chưa từng đến trung tâm. Lần này, thành công được đo bằng việc khách có đến đúng nơi mà không cần hỗ trợ hay không. Trải nghiệm cho thấy đơn giản không chỉ là ít chi tiết, mà là giữ chi tiết các nhóm người dùng cần.")],
[('unnecessary','không cần thiết',0),('assumed','cho rằng khi chưa kiểm chứng',0),('exposed','bộc lộ',1),('distinguish','phân biệt',1),('step-free','không có bậc thang',2),('retaining','giữ lại',2)],[
('detail','What did the initial staff review focus on?',['The appearance of the map','Wheelchair users finding their way','The cost of rebuilding the centre'],0,0,'staff praised its clean appearance','Nhân viên đánh giá hình thức rõ ràng trước khi kiểm tra người dùng thực tế.'),
('inference','Which principle is best supported by the redesign?',['Useful simplicity depends on user needs','All details should always be removed','Colour should replace every written label'],0,2,'retaining the details that different users need.','Kết luận nhấn mạnh giữ thông tin cần thiết với người dùng, không phải xóa càng nhiều càng tốt.'),
('tfng','The revised map used both numbers and colours for floors.',TF,0,2,'added floor numbers alongside colours.','Bản sửa kết hợp số tầng và màu: TRUE.')])

lesson('b2-the-cost-of-free-delivery','The Cost of Free Delivery','B2','Tiêu dùng & lựa chọn','Cân nhắc tổng chi phí khi một đơn hàng được miễn phí giao hàng.',[
("Maya intended to order a replacement cable from an online shop. At checkout, a message told her that she was only a small amount away from qualifying for free delivery. She added a notebook she did not need immediately. The delivery charge disappeared, and for a moment the purchase felt like a saving. Only later did she notice that the total payment was higher than it would have been with the cable and paid delivery alone.","Maya định đặt một dây cáp thay thế từ cửa hàng trực tuyến. Khi thanh toán, thông báo nói cô chỉ thiếu một khoản nhỏ để được miễn phí giao hàng. Cô thêm cuốn sổ chưa cần ngay. Phí vận chuyển biến mất và thoáng chốc cô thấy như mình tiết kiệm được tiền. Sau đó cô mới nhận ra tổng tiền cao hơn phương án chỉ mua dây cáp và trả phí giao hàng."),
("She began comparing orders in a different way. Instead of asking whether delivery was free, she asked how much she would spend to obtain the items she actually needed. Sometimes adding another item made sense: a household product she would otherwise buy next week could reduce a future trip. But an unfamiliar snack or decorative object was harder to justify. The label on the charge mattered less than the final cost and usefulness of the basket.","Cô bắt đầu so sánh đơn hàng theo cách khác. Thay vì hỏi giao hàng có miễn phí không, cô hỏi mình phải chi bao nhiêu cho những món thực sự cần. Đôi khi thêm hàng là hợp lý: một đồ gia dụng tuần sau vẫn phải mua có thể giúp bớt một chuyến đi. Nhưng đồ ăn lạ hay đồ trang trí thì khó biện minh hơn. Tên khoản phí ít quan trọng hơn tổng tiền và tính hữu ích của giỏ hàng."),
("Maya did not conclude that free-delivery offers were always bad. A promotion could be useful when it matched an existing plan. What troubled her was how easily the offer had changed the question she was trying to answer. She now keeps a short shopping list beside her screen. Before adding anything, she checks whether she wanted it before seeing the promotion. The pause does not guarantee a perfect decision, but it makes the decision more deliberate.","Maya không kết luận ưu đãi miễn phí giao hàng luôn xấu. Khuyến mãi có thể hữu ích khi phù hợp kế hoạch sẵn có. Điều khiến cô băn khoăn là ưu đãi dễ dàng thay đổi câu hỏi ban đầu của mình. Giờ cô để danh sách mua sắm ngắn cạnh màn hình. Trước khi thêm hàng, cô kiểm tra xem mình có muốn món đó trước khi thấy khuyến mãi không. Việc dừng lại không đảm bảo quyết định hoàn hảo nhưng giúp cô cân nhắc có chủ ý hơn.")],
[('qualifying','đáp ứng điều kiện',0),('purchase','việc mua hàng',0),('justify','đưa ra lý do hợp lý cho',1),('usefulness','tính hữu ích',1),('promotion','chương trình khuyến mãi',2),('deliberate','có chủ ý, được cân nhắc',2)],[
('detail','Why did Maya add the notebook?',['To qualify for free delivery','Her old notebook was full','The cable was unavailable'],0,0,'only a small amount away from qualifying for free delivery.','Cô thêm sổ để đạt ngưỡng miễn phí giao hàng.'),
('inference','What does Maya now consider most important?',['Total spending on useful items','Removing every delivery charge','Buying all discounted products'],0,1,'the final cost and usefulness of the basket.','Cô quan tâm tổng chi phí và tính hữu ích của hàng mua.'),
('tfng','Maya believes every free-delivery promotion is harmful.',TF,1,2,'Maya did not conclude that free-delivery offers were always bad.','Bài phủ định quan điểm tuyệt đối này: FALSE.')])

lesson('c1-the-measurement-trap','The Measurement Trap','C1','Dữ liệu & quyết định','Khi chỉ số đại diện trở thành mục tiêu, điều gì có thể bị bỏ quên?',[
("A fictional adult-learning centre introduced a dashboard to help tutors identify students who needed support. The dashboard counted completed online exercises, a measure that was easy to collect and compare. Initially, tutors treated the count as one clue among many. A learner completing fewer exercises might be struggling, but might equally be spending longer on a challenging passage. Conversations with students remained essential to interpreting the numbers.","Một trung tâm giáo dục người lớn giả định giới thiệu bảng số liệu để giúp giáo viên xác định học viên cần hỗ trợ. Bảng đếm bài tập trực tuyến đã hoàn thành, một chỉ số dễ thu thập và so sánh. Ban đầu giáo viên xem nó là một dấu hiệu trong nhiều dấu hiệu. Người làm ít bài có thể đang gặp khó khăn, nhưng cũng có thể dành nhiều thời gian cho đoạn đọc khó. Trò chuyện với học viên vẫn thiết yếu để diễn giải số liệu."),
("The meaning of the measure changed when management began rewarding classes with the highest completion totals. Tutors had an incentive to assign shorter exercises, and some learners discovered that repeating familiar tasks raised their scores quickly. None of this required anyone to falsify a record. The data could be accurate while becoming less informative about the educational outcome the centre actually valued: independent understanding of unfamiliar texts.","Ý nghĩa của chỉ số thay đổi khi ban quản lý bắt đầu thưởng các lớp có tổng số bài hoàn thành cao nhất. Giáo viên có động lực giao bài ngắn hơn; một số học viên nhận ra làm lại bài quen giúp tăng điểm nhanh. Không ai cần làm giả hồ sơ. Dữ liệu vẫn chính xác nhưng ít phản ánh kết quả giáo dục mà trung tâm thật sự coi trọng: khả năng độc lập hiểu văn bản chưa quen."),
("In response, the centre added reading discussions and occasional unfamiliar tasks to its reviews. It did not discard the dashboard, which still revealed useful patterns of participation. Instead, managers removed the competition between classes and asked tutors to explain apparent changes before drawing conclusions. This made evaluation slower, but also reduced the pressure to optimise a single visible number. The lesson was not that measurement is inherently misleading. It was that a proxy becomes fragile when people are rewarded for improving it without improving what it is meant to represent.","Trung tâm đáp lại bằng cách thêm thảo luận đọc hiểu và đôi lúc giao bài lạ vào đánh giá. Họ không bỏ bảng số liệu vì nó vẫn cho thấy xu hướng tham gia hữu ích. Thay vào đó, quản lý bỏ cuộc thi giữa các lớp và yêu cầu giáo viên giải thích thay đổi trước khi kết luận. Việc đánh giá chậm hơn nhưng giảm áp lực tối ưu một con số duy nhất. Bài học không phải đo lường vốn gây hiểu lầm, mà là chỉ số đại diện trở nên mong manh khi người ta được thưởng vì cải thiện nó mà không cải thiện điều nó đại diện.")],
[('interpreting','diễn giải',0),('incentive','động lực hoặc lợi ích thúc đẩy',1),('falsify','làm giả',1),('discard','loại bỏ',2),('proxy','chỉ số đại diện gián tiếp',2),('fragile','dễ mất độ tin cậy trong ngữ cảnh này',2)],[
('inference','Why could accurate exercise counts become less useful?',['Incentives changed what people chose to complete','The software stopped recording submissions','All learners deliberately falsified their results'],0,1,'repeating familiar tasks raised their scores quickly.','Lựa chọn bài quen/ngắn làm số đếm tăng mà chưa chắc tăng năng lực đọc mới.'),
('detail','What did managers remove?',['Competition between classes','All online exercises','Every discussion with learners'],0,2,'managers removed the competition between classes','Trung tâm bỏ thi đua giữa lớp, không bỏ toàn bộ dữ liệu hay bài tập.'),
('tfng','The centre abandoned its dashboard completely.',TF,1,2,'It did not discard the dashboard','Trung tâm giữ bảng số liệu và kết hợp thêm cách đánh giá.')])

lesson('c1-preserving-a-changing-place','Preserving a Changing Place','C1','Di sản & đô thị','Cân nhắc ý nghĩa của bảo tồn khi một khu phố vẫn đang được sử dụng.',[
("In an imagined riverside town, a proposal to preserve an old market provoked an unexpected disagreement. Supporters agreed that the building mattered, but they disagreed about what preservation should protect. An architectural group emphasised the original roof and stone frontage. Traders were more concerned with affordable rents, access for deliveries and enough shelter to continue working through winter. A beautifully restored market without its familiar stalls, they argued, would preserve a structure while losing much of its purpose.","Tại một thị trấn ven sông giả định, đề xuất bảo tồn chợ cũ gây ra bất đồng bất ngờ. Những người ủng hộ đồng ý tòa nhà quan trọng nhưng không thống nhất cần bảo vệ điều gì. Nhóm kiến trúc nhấn mạnh mái và mặt tiền đá nguyên bản. Tiểu thương quan tâm hơn tới giá thuê vừa sức, lối giao hàng và mái che đủ để làm việc mùa đông. Họ cho rằng một ngôi chợ được phục hồi đẹp nhưng thiếu các quầy quen thuộc sẽ giữ cấu trúc mà mất phần lớn mục đích."),
("The initial consultation invited residents to comment on drawings displayed in the town hall. Attendance was respectable, yet several long-established traders were absent because the meetings coincided with their busiest hours. When organisers later visited the market before opening time, they heard concerns that had barely appeared in the written responses. The difference did not demonstrate that one group cared more than another. It showed how the design of participation could influence whose understanding of a place became visible.","Cuộc tham vấn đầu mời cư dân nhận xét bản vẽ trưng bày tại tòa thị chính. Số người tham dự khá tốt nhưng một số tiểu thương lâu năm vắng mặt vì họp trùng giờ bận nhất. Khi ban tổ chức đến chợ trước giờ mở cửa, họ nghe những lo ngại gần như không xuất hiện trong phản hồi viết. Khác biệt không chứng tỏ nhóm nào quan tâm hơn, mà cho thấy cách tổ chức tham gia ảnh hưởng đến việc cách nhìn của ai được thể hiện."),
("The revised proposal retained the frontage while permitting reversible changes behind it. It also phased construction so that part of the market could remain open. These compromises satisfied neither every trader nor every conservation enthusiast, and the future rental arrangements still required negotiation. Nevertheless, discussion had shifted from choosing between change and preservation to deciding which changes could sustain the market's continuing life. Protecting a place, in this account, required attention to the relationships and activities that made its physical features meaningful.","Đề xuất sửa đổi giữ mặt tiền nhưng cho phép thay đổi có thể hoàn nguyên phía sau. Việc xây dựng cũng chia giai đoạn để một phần chợ tiếp tục mở. Thỏa hiệp không làm mọi tiểu thương hay người yêu bảo tồn hài lòng, và tiền thuê tương lai vẫn cần thương lượng. Dù vậy, cuộc thảo luận chuyển từ lựa chọn giữa thay đổi và bảo tồn sang quyết định thay đổi nào duy trì đời sống của chợ. Trong câu chuyện này, bảo vệ nơi chốn đòi hỏi quan tâm tới quan hệ và hoạt động tạo ý nghĩa cho đặc điểm vật chất của nó.")],
[('preservation','sự bảo tồn',0),('frontage','mặt tiền',0),('coincided','trùng thời điểm',1),('participation','sự tham gia',1),('reversible','có thể hoàn nguyên',2),('sustain','duy trì',2)],[
('detail','Why were some traders absent from the first meetings?',['The meetings overlapped with busy working hours','They opposed all renovation','They were forbidden to attend'],0,1,'the meetings coincided with their busiest hours.','Thời gian họp trùng giờ làm việc bận, không chứng minh họ thiếu quan tâm.'),
('inference','What broader idea does the account support?',['Preservation includes the activities that give a place meaning','Physical appearance is the only value worth protecting','Consultation eliminates every disagreement'],0,2,'the relationships and activities that made its physical features meaningful.','Bảo tồn cần xét cả hoạt động và quan hệ gắn với không gian.'),
('tfng','The revised proposal resolved every disagreement about the market.',TF,1,2,'These compromises satisfied neither every trader nor every conservation enthusiast','Vẫn còn bất đồng và vấn đề thuê phải thương lượng: FALSE.')])

lesson('ielts-a-library-of-seeds','A Library of Seeds','B1','IELTS · Môi trường','Luyện tìm chi tiết và phân biệt thông tin bị phủ định với thông tin không được đề cập.',[
("Consider a hypothetical seed-sharing project in a small town. The public library already lends books, but a group of local gardeners suggests that it could also help people grow food. They place a wooden cabinet near the entrance and fill it with packets of seeds donated by residents. Unlike books, seeds cannot be returned in their original condition. Participants are therefore invited, rather than required, to bring back seeds from plants they successfully grow. Beginners can take part even if they have nothing to contribute at first.","Hãy xét một dự án chia sẻ hạt giống giả định tại thị trấn nhỏ. Thư viện công cộng vốn cho mượn sách, nhưng nhóm người làm vườn địa phương đề xuất hỗ trợ trồng thực phẩm. Họ đặt tủ gỗ gần cửa và cho vào các gói hạt do cư dân tặng. Khác sách, hạt giống không thể được trả lại nguyên trạng. Vì vậy người tham gia được khuyến khích, chứ không bắt buộc, mang hạt từ cây đã trồng thành công trở lại. Người mới có thể tham gia dù lúc đầu chưa có gì đóng góp."),
("The first difficulty is not a shortage of seeds but a shortage of useful information. Some packets have attractive names without instructions. Others contain seeds from plants whose growing conditions are unclear. The volunteers introduce a simple label recording the plant's name, the year the seeds were collected and any available growing advice. They do not promise that every seed will grow. Storage conditions and the age of a seed can affect the result, and a label cannot remove that uncertainty.","Khó khăn đầu tiên không phải thiếu hạt mà thiếu thông tin hữu ích. Một số gói có tên hấp dẫn nhưng không có hướng dẫn; số khác chứa hạt từ cây có điều kiện sinh trưởng chưa rõ. Tình nguyện viên tạo nhãn đơn giản ghi tên cây, năm thu hạt và lời khuyên trồng nếu có. Họ không hứa mọi hạt đều nảy mầm. Điều kiện bảo quản và tuổi hạt ảnh hưởng kết quả, nhãn không xóa được sự bất định đó."),
("A second challenge concerns the library's limited space. Large bags of soil and heavy tools cannot be stored beside the books. Instead of expanding the cabinet indefinitely, the group arranges occasional meetings in a nearby community garden. Experienced growers demonstrate planting methods, while new participants describe what went wrong with their first attempts. These conversations are valuable because a packet of seeds alone cannot explain every problem a gardener may encounter. The meetings also give people a reason to return even when they do not need more seeds.","Thách thức thứ hai là không gian hạn chế của thư viện. Túi đất lớn và dụng cụ nặng không thể để cạnh sách. Thay vì mở rộng tủ vô hạn, nhóm thỉnh thoảng tổ chức gặp ở vườn cộng đồng gần đó. Người có kinh nghiệm trình diễn cách trồng; người mới mô tả vấn đề trong lần thử đầu. Trò chuyện có ích vì chỉ một gói hạt không giải thích được mọi vấn đề người trồng gặp. Buổi gặp còn tạo lý do quay lại dù họ chưa cần hạt mới."),
("At the end of the first season, the organisers count the packets taken from the cabinet. However, they recognise that this number does not show how many plants survived or whether people felt more confident about gardening. They invite participants to share short accounts of their experience. Some report successful harvests; others explain that their plants failed but that they want to try again. The organisers decide to retain both types of account. In this imagined project, learning from an unsuccessful attempt is part of the value of sharing, rather than evidence that the entire idea has failed.","Cuối mùa đầu, ban tổ chức đếm số gói được lấy. Tuy nhiên họ nhận ra con số không cho biết bao nhiêu cây sống hay người tham gia có tự tin hơn không. Họ mời người tham gia chia sẻ trải nghiệm ngắn. Có người thu hoạch thành công; người khác nói cây chết nhưng muốn thử lại. Ban tổ chức giữ cả hai kiểu chia sẻ. Trong dự án giả định này, học từ lần thử thất bại là một phần giá trị chia sẻ, không phải bằng chứng cả ý tưởng thất bại.")],
[('contribute','đóng góp',0),('shortage','sự thiếu hụt',1),('uncertainty','sự không chắc chắn',1),('encounter','gặp phải',2),('retain','giữ lại',3),('harvests','các vụ hoặc lượng thu hoạch',3)],[
('detail','What information is included on the new labels?',['The year the seeds were collected','A guarantee that every seed will grow','The price of the original plant','The age of the gardener'],0,1,"the year the seeds were collected",'Nhãn ghi năm thu hạt, không đảm bảo nảy mầm.'),
('detail','Why are some meetings held in a community garden?',['The library has limited space for gardening materials','The library has stopped lending books','Participants are forbidden to speak inside the library','All volunteers live next to the garden'],0,2,"the library's limited space",'Không gian thư viện hạn chế, nên hoạt động thực hành chuyển sang vườn cộng đồng.'),
('tfng','New participants must donate seeds before taking any.',TF,1,0,'Beginners can take part even if they have nothing to contribute at first.','Không cần đóng góp trước: nhận định trái nội dung, chọn FALSE.'),
('tfng','The label cannot guarantee successful growth.',TF,0,1,'They do not promise that every seed will grow.','Không có cam kết mọi hạt nảy mầm: TRUE.'),
('tfng','Most participants grow their plants on balconies.',TF,2,2,'new participants describe what went wrong with their first attempts.','Bài có nói người tham gia kể trải nghiệm nhưng không nêu phần lớn trồng ở đâu. Không suy đoán: NOT GIVEN.'),
('tfng','The organisers keep accounts of both successful and unsuccessful attempts.',TF,0,3,'The organisers decide to retain both types of account.','Hai kiểu trải nghiệm đều được giữ lại: TRUE.')],track='ielts')

lesson('ielts-a-cooler-street','A Cooler Street','B2','IELTS · Đô thị','Đọc một thử nghiệm giả định, xác định mục tiêu đo lường và tránh suy luận vượt quá bằng chứng.',[
("Imagine a coastal town deciding how to make a busy pedestrian street more comfortable during summer. Shopkeepers complain that customers avoid the street in the early afternoon, while residents ask for more places to sit. The council receives two proposals: plant additional trees or replace dark paving with a lighter surface. Both proposals sound plausible, but the council does not have enough money to apply both along the entire street. It therefore chooses a small trial before committing to a larger investment. The trial is designed to compare practical benefits, not to establish a universal rule for every city.","Hãy hình dung thị trấn ven biển tìm cách làm phố đi bộ đông đúc dễ chịu hơn mùa hè. Chủ cửa hàng phàn nàn khách tránh phố vào đầu chiều, cư dân muốn thêm chỗ ngồi. Hội đồng nhận hai đề xuất: trồng thêm cây hoặc thay nền tối bằng bề mặt sáng. Cả hai có vẻ hợp lý nhưng không đủ tiền thực hiện toàn tuyến. Vì vậy họ thử nhỏ trước khi đầu tư lớn. Mục đích là so lợi ích thực tế, không xác lập quy tắc chung cho mọi thành phố."),
("Three short sections are selected. One receives temporary shade structures intended to approximate some effects of tree cover. Another receives a light-coloured surface coating, and a third remains unchanged for comparison. The sections are not identical: the buildings differ in height and one section is closer to the sea. To make the comparison more informative, staff record conditions in all three locations before and after the changes. They also note the weather and the time of each observation. Without this information, a cooler reading might simply reflect a cloud passing overhead rather than the intervention itself.","Ba đoạn ngắn được chọn. Một đoạn có cấu trúc che tạm để mô phỏng một phần tác dụng tán cây. Đoạn khác phủ lớp màu sáng; đoạn ba giữ nguyên để so sánh. Các đoạn không giống hệt: chiều cao tòa nhà khác và một đoạn gần biển hơn. Để so sánh có ý nghĩa hơn, nhân viên ghi điều kiện cả ba nơi trước và sau thay đổi, cả thời tiết và giờ quan sát. Thiếu thông tin ấy, nhiệt độ thấp hơn có thể chỉ do mây đi qua chứ không phải can thiệp."),
("The monitoring team initially plans to measure only surface temperature. A local access group points out that people experience more than the temperature of the ground. They may be exposed to sunlight, reflected light and hot air, and they may need to wait rather than keep walking. The team therefore adds shaded and unshaded seating observations and brief interviews with people using the street. These interviews are not treated as precise thermometers. Instead, they provide information about comfort and use that a surface measurement cannot supply on its own.","Nhóm giám sát ban đầu định chỉ đo nhiệt độ bề mặt. Nhóm tiếp cận địa phương chỉ ra con người trải nghiệm nhiều hơn nhiệt độ nền: họ chịu nắng, ánh sáng phản xạ, khí nóng và có thể phải chờ thay vì đi liên tục. Vì vậy nhóm thêm quan sát chỗ ngồi có và không có bóng râm, cùng phỏng vấn ngắn người dùng phố. Phỏng vấn không được xem là nhiệt kế chính xác mà bổ sung thông tin về sự dễ chịu và cách sử dụng mà đo bề mặt không tự cung cấp được."),
("At the end of the trial, the council resists selecting a winner from a single average figure. A design that performs well at midday may offer fewer benefits in the evening, and temporary shade says little about the watering and maintenance that real trees would require. The final report recommends a combination of measures in different locations, together with a budget for upkeep. It also lists unresolved questions, including how the surfaces will perform after several years of wear. In this hypothetical example, the purpose of a trial is to reduce uncertainty enough to support a decision, not to make uncertainty disappear.","Cuối thử nghiệm, hội đồng không chọn phương án thắng chỉ từ một số trung bình. Thiết kế tốt buổi trưa có thể ít lợi ích hơn tối; mái che tạm không cho biết nhiều về tưới và chăm cây thật. Báo cáo cuối đề nghị kết hợp biện pháp ở các vị trí khác nhau, kèm ngân sách bảo trì. Báo cáo liệt kê câu hỏi chưa giải quyết, như bề mặt hoạt động ra sao sau nhiều năm mòn. Trong ví dụ giả định này, thử nghiệm nhằm giảm bất định đủ để ra quyết định, không xóa hoàn toàn bất định.")],
[('plausible','có vẻ hợp lý',0),('committing','cam kết dành nguồn lực',0),('approximate','mô phỏng hoặc xấp xỉ',1),('intervention','biện pháp can thiệp',1),('reflected','được phản xạ',2),('upkeep','việc bảo trì',3)],[
('main_idea','What is the main purpose of the trial?',['To inform a local spending decision','To prove a rule that applies to every city','To remove all uncertainty about summer weather','To stop customers entering the street'],0,0,'It therefore chooses a small trial before committing to a larger investment.','Thử nghiệm hỗ trợ quyết định đầu tư địa phương, không chứng minh quy tắc phổ quát.'),
('detail','Why does the team add interviews?',['To learn about comfort and how people use the street','To replace every temperature measurement','To calculate the exact height of each building','To select the most popular shop'],0,2,'information about comfort and use that a surface measurement cannot supply on its own.','Phỏng vấn bổ sung trải nghiệm sử dụng mà số đo bề mặt không đủ phản ánh.'),
('tfng','All three trial sections have identical surrounding conditions.',TF,1,1,'The sections are not identical','Các đoạn không có điều kiện giống hệt: FALSE.'),
('tfng','Staff record the weather when taking observations.',TF,0,1,'They also note the weather and the time of each observation.','Thời tiết và thời điểm đều được ghi: TRUE.'),
('tfng','The council publishes the report in three languages.',TF,2,3,'The final report recommends a combination of measures in different locations','Bài nói nội dung báo cáo nhưng không nói ngôn ngữ xuất bản: NOT GIVEN.'),
('tfng','The trial determines how the surfaces will perform after several years.',TF,1,3,'unresolved questions, including how the surfaces will perform after several years of wear.','Độ bền sau nhiều năm vẫn là câu hỏi chưa giải quyết: FALSE.')],track='ielts')

lesson('ielts-the-searchable-archive','The Searchable Archive','C1','IELTS · Công nghệ & lịch sử','Luyện đọc lập luận về số hóa, sai lệch chọn mẫu và điều dữ liệu không thể hiện.',[
("Consider an imaginary municipal archive that decides to digitise its collection of local newspapers. For decades, researchers have consulted fragile bound volumes in a reading room with limited opening hours. Digitisation promises to make these records available to people who cannot travel to the archive. A searchable collection might also reveal references that a researcher browsing page by page would miss. The project is therefore presented as an expansion of access. Yet the transformation from paper to searchable text introduces choices that can shape what users find, even when no one intends to alter the historical record.","Hãy xét kho lưu trữ đô thị giả định quyết định số hóa báo địa phương. Hàng thập kỷ, nhà nghiên cứu xem các tập đóng gáy dễ hỏng trong phòng có giờ mở hạn chế. Số hóa hứa hẹn đưa tài liệu tới người không thể đến trực tiếp. Tìm kiếm có thể phát hiện chi tiết đọc từng trang dễ bỏ sót. Vì vậy dự án được giới thiệu là mở rộng tiếp cận. Tuy nhiên, chuyển giấy thành văn bản tìm kiếm được chứa những lựa chọn định hình kết quả người dùng thấy, ngay cả khi không ai định sửa lịch sử."),
("The first choice concerns selection. With funding available for only part of the collection, the team prioritises volumes that can be scanned without extensive conservation work. This is reasonable from a practical perspective, but it means that damaged issues are less likely to appear online. A user who sees only the digital catalogue may mistake this absence for evidence that a newspaper was never published on certain dates. To address the problem, archivists retain catalogue entries for undigitised material and explain why some items cannot yet be viewed. They distinguish an absent digital image from an absent historical document.","Lựa chọn đầu là tuyển tài liệu. Với kinh phí chỉ đủ một phần, nhóm ưu tiên tập có thể quét mà không cần bảo quản sửa chữa lớn. Điều này thực tế nhưng làm số báo hỏng ít xuất hiện trực tuyến hơn. Người chỉ xem danh mục số có thể nhầm rằng báo chưa từng phát hành ngày đó. Để giải quyết, nhân viên giữ mục danh mục cho tài liệu chưa số hóa và giải thích vì sao chưa xem được. Họ phân biệt thiếu ảnh số với thiếu tài liệu lịch sử."),
("The second choice concerns transcription. Software converts the scanned pages into text, but decorative headings, stained paper and unusual typefaces can produce errors. These errors are not distributed evenly. A common word printed clearly may be recognised reliably, while a family name in a damaged advertisement may be distorted beyond recognition. A failed search therefore does not necessarily establish that a name is absent from the newspaper. The archive provides page images alongside the searchable text and invites users to report mistakes, while warning that corrected text will remain incomplete for some time.","Lựa chọn thứ hai liên quan chuyển thành chữ. Phần mềm chuyển trang quét thành văn bản nhưng tiêu đề trang trí, giấy ố và kiểu chữ lạ có thể gây lỗi. Lỗi không phân bố đều: từ phổ biến in rõ có thể nhận diện tốt, còn họ tên trong quảng cáo hỏng có thể méo tới mức không nhận ra. Tìm không ra không nhất thiết chứng minh tên không có trên báo. Kho cung cấp ảnh trang bên cạnh chữ tìm kiếm được, mời báo lỗi và lưu ý việc sửa còn chưa đầy đủ trong một thời gian."),
("Finally, the project changes the habits of research. Searching for a known term is efficient, but browsing an entire page can expose neighbouring reports, advertisements or editorial arrangements that change its meaning. Neither method is inherently superior; they answer different questions. The archive designs its interface so that a search result leads to the full page rather than to an isolated sentence alone. It also documents the scope and limitations of the digitised collection. In this hypothetical case, responsible access involves more than placing documents online. It requires making the boundaries of the available evidence visible, so that convenience is not mistaken for completeness.","Cuối cùng, dự án thay đổi thói quen nghiên cứu. Tìm thuật ngữ đã biết hiệu quả nhưng xem cả trang có thể thấy tin, quảng cáo hay cách biên tập cạnh đó làm đổi ý nghĩa. Không cách nào vốn vượt trội; chúng trả lời câu hỏi khác nhau. Giao diện dẫn từ kết quả tìm tới cả trang thay vì chỉ câu tách rời. Kho cũng ghi phạm vi và giới hạn bộ số hóa. Trong trường hợp giả định này, tiếp cận có trách nhiệm không chỉ là đưa tài liệu lên mạng, mà phải làm rõ giới hạn bằng chứng để sự tiện lợi không bị nhầm với tính đầy đủ.")],
[('fragile','dễ hỏng',0),('conservation','bảo quản, phục chế',1),('distinguish','phân biệt',1),('transcription','chuyển hình ảnh chữ thành văn bản',2),('distributed','được phân bố',2),('completeness','tính đầy đủ',3)],[
('detail','Why are some volumes prioritised for scanning?',['They need less conservation work','They mention more famous families','They contain only advertisements','They were published most recently'],0,1,'volumes that can be scanned without extensive conservation work.','Tiêu chí được nêu là ít cần công việc bảo quản lớn, không phải độ nổi tiếng hay ngày mới nhất.'),
('inference','What central caution does the passage offer?',['Convenient digital access does not guarantee complete evidence','Digitisation necessarily destroys historical documents','Searching should replace browsing in all research','Every transcription error is deliberately introduced'],0,3,'so that convenience is not mistaken for completeness.','Tác giả nhấn mạnh không nhầm tiện lợi với đầy đủ.'),
('tfng','The online catalogue keeps entries for some items that have not been digitised.',TF,0,1,'archivists retain catalogue entries for undigitised material','Danh mục vẫn có mục tài liệu chưa số hóa: TRUE.'),
('tfng','Transcription errors affect every kind of text equally.',TF,1,2,'These errors are not distributed evenly.','Lỗi không phân bố đồng đều: FALSE.'),
('tfng','Users receive a payment for reporting transcription errors.',TF,2,2,'invites users to report mistakes','Mời báo lỗi không đồng nghĩa có trả tiền. Bài không nêu thù lao: NOT GIVEN.'),
('tfng','A search result allows users to view the complete newspaper page.',TF,0,3,'a search result leads to the full page rather than to an isolated sentence alone.','Giao diện dẫn tới cả trang báo: TRUE.')],track='ielts')

